from pathlib import Path
import sys,subprocess,json
D=Path(__file__).parent;sys.path.insert(0,str(D.parent));from remote import command
js="""const {refreshSearchCanaryLease,searchCanarySelection}=await import('./src/search-canary-runtime.js');await refreshSearchCanaryLease();const target=['BJP00326070803800006','BJP00326060100100004'];const baseline=process.env.ONESHOT_FIRST_TURN_AGENT_NAME||'rust-worker';const selected=target.map(sn=>({sn,...searchCanarySelection(sn,baseline,true)}));const negative=searchCanarySelection('BJP00399999999999902',baseline,true);if(selected.some(x=>!x.canary||x.reason!=='selected')||negative.canary||negative.reason!=='not_target')throw Error('selection assertions');const {deviceRegistryStore}=await import('./src/device-registry-store.js');const identities=target.map(sn=>{const d=deviceRegistryStore.get(sn);if(d?.status!=='active'||!d.account_id)throw Error('device registry mismatch');return {sn,registered:true,status:d.status,account_linked:true};});console.log(JSON.stringify({selected,negative,identities}));"""
code=r"""import pathlib,subprocess,sqlite3,json,time,os,hashlib,urllib.request
r=pathlib.Path('/opt/p003/search-canary-20261021/brain');main=pathlib.Path('/opt/p003/server');b=pathlib.Path(__BACKUP__);spec=__SPEC__;manifest=json.loads((b/'r22-install.json').read_text());assert (b/'r22-open.json').exists();assert hashlib.sha256((r/'bin/search-route-preview').read_bytes()).hexdigest()==spec['preview_sha256'];assert all(hashlib.sha256((r/n).read_bytes()).hexdigest()==h for n,h in spec['source'].items())
env=dict(os.environ);env['SEARCH_CANARY_HEALTH_FILE']=str(r/'health.json');p=subprocess.run(['node','--experimental-sqlite','--env-file=.env.local','--import','tsx','--input-type=module','-e',__JS__],cwd=main,env=env,text=True,capture_output=True,timeout=15);assert p.returncode==0,'selection failed';selection=json.loads(p.stdout.strip().splitlines()[-1]);flags={}
for n,root in [('main',main),('candidate',r)]:
 d=sqlite3.connect('file:'+str(root/'data/config.db')+'?mode=ro',uri=True);flags[n]=dict(d.execute("select key,value from runtime_flag where key like 'p003.search.%'"));d.close()
snap=json.loads((b/'manifest.json').read_text());assert flags['main']==snap['main_flags']and flags['candidate']==snap['candidate_flags']
d=sqlite3.connect('file:'+str(main/'data/ota.db')+'?mode=ro',uri=True);d.row_factory=sqlite3.Row;versions=[dict(x)for x in d.execute('select sn,version_code,version_name,last_check_at from ota_device_status where sn in (?,?)',('BJP00326070803800006','BJP00326060100100004'))];d.close();rel=json.loads((r/'release-status.json').read_text());safe={k:rel.get(k)for k in ['revision','verified_at_ms','brain_commit','worker_commit','worker_sha256','worker_tests','brain_tests','real_device_acceptance','r22_deployed_at_ms','p1','p2']};assert safe['worker_commit']==spec['worker_code_commit'];assert safe['worker_sha256']==spec['worker_sha256']
print(json.dumps({'at_ms':int(time.time()*1000),'selection':selection,'flags':flags,'versions':versions,'release':safe,'main_health':json.load(urllib.request.urlopen('http://127.0.0.1:3001/health',timeout=3)),'candidate_health':json.load(urllib.request.urlopen('http://127.0.0.1:3007/health',timeout=3)),'pm2':[{'name':p['name'],'pid':p['pid'],'restarts':p['pm2_env']['restart_time']}for p in json.loads(subprocess.check_output(['pm2','jlist'],text=True))],'timer':subprocess.check_output(['systemctl','show','p003-search-expire-session13-20261026T031900Z.timer','-p','ActiveState','-p','NextElapseUSecRealtime'],text=True)}))
""".replace('__JS__',repr(js))
spec=json.loads((D/'release-http2-spec.json').read_text());session=json.loads((D/'release-http2-session.json').read_text());code=code.replace('__SPEC__',repr(spec)).replace('__BACKUP__',repr('/opt/p003/backups/'+session['label']));compile(code,'selection-postcheck','exec')
p=subprocess.run(command('brain','python3 -'),input=code,text=True,capture_output=True,timeout=55);(D/'selection-http2-postcheck.stderr').write_text(p.stderr);assert p.returncode==0,'selection postcheck failed';v=json.loads(p.stdout);(D/'selection-http2-postcheck.json').write_text(json.dumps(v));print(json.dumps(v))
